import os
import hashlib
import hmac
import secrets
import sqlite3
import re
from pathlib import Path, PurePosixPath
from urllib.parse import unquote, quote
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import threading
import time

SECRET_KEY = secrets.token_bytes(32)
DATA_ROOT = "/var/app/storage"
DB_PATH = "/var/app/metadata.db"
MAX_FILE_SIZE = 10 * 1024 * 1024
ALLOWED_EXTENSIONS = {".txt", ".pdf", ".png", ".jpg", ".dat"}

def init_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("""
        CREATE TABLE IF NOT EXISTS files (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            owner TEXT NOT NULL,
            filename TEXT NOT NULL,
            storage_key TEXT NOT NULL,
            content_hash TEXT NOT NULL,
            created_at REAL NOT NULL,
            is_public INTEGER DEFAULT 0
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS sessions (
            token TEXT PRIMARY KEY,
            username TEXT NOT NULL,
            expires_at REAL NOT NULL
        )
    """)
    conn.commit()
    return conn

def generate_storage_key(owner, filename):
    """Generate a unique storage key for a file."""
    random_part = secrets.token_hex(16)
    return f"{owner}/{random_part}/{filename}"

def validate_filename(filename):
    """Strict filename validation."""
    if not filename or len(filename) > 255:
        return None
    cleaned = PurePosixPath(filename).name
    if not cleaned or cleaned.startswith("."):
        return None
    if not re.match(r'^[a-zA-Z0-9][a-zA-Z0-9._-]*$', cleaned):
        return None
    ext = os.path.splitext(cleaned)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return None
    return cleaned

def validate_owner(owner):
    """Strict owner/username validation."""
    if not owner or len(owner) > 64:
        return None
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9_-]{2,63}$', owner):
        return None
    return owner

def compute_hmac_tag(data):
    """Compute HMAC-SHA256 for integrity verification."""
    return hmac.new(SECRET_KEY, data, hashlib.sha256).hexdigest()

def compute_content_hash(data):
    """SHA-256 content hash for deduplication."""
    return hashlib.sha256(data).hexdigest()

def get_storage_path(storage_key):
    """Resolve storage key to filesystem path with containment check."""
    full_path = os.path.normpath(os.path.join(DATA_ROOT, storage_key))
    if not full_path.startswith(DATA_ROOT + os.sep):
        raise ValueError("Path traversal detected")
    return full_path

def store_file(owner, filename, content):
    """Store a file securely."""
    validated_name = validate_filename(filename)
    if not validated_name:
        return {"error": "Invalid filename"}
    validated_owner = validate_owner(owner)
    if not validated_owner:
        return {"error": "Invalid owner"}
    if len(content) > MAX_FILE_SIZE:
        return {"error": "File too large"}

    content_hash = compute_content_hash(content)
    storage_key = generate_storage_key(validated_owner, validated_name)
    storage_path = get_storage_path(storage_key)

    os.makedirs(os.path.dirname(storage_path), exist_ok=True)
    with open(storage_path, 'wb') as f:
        f.write(content)

    conn = sqlite3.connect(DB_PATH)
    conn.execute(
        "INSERT INTO files (owner, filename, storage_key, content_hash, created_at) VALUES (?, ?, ?, ?, ?)",
        (validated_owner, validated_name, storage_key, content_hash, time.time())
    )
    conn.commit()
    conn.close()

    return {"success": True, "storage_key": storage_key}

def retrieve_file(requesting_user, file_id):
    """Retrieve a file with access control."""
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.execute(
        "SELECT owner, filename, storage_key, is_public FROM files WHERE id = ?",
        (file_id,)
    )
    row = cursor.fetchone()
    conn.close()

    if not row:
        return {"error": "File not found"}

    owner, filename, storage_key, is_public = row

    if not is_public and owner != requesting_user:
        return {"error": "Access denied"}

    storage_path = get_storage_path(storage_key)

    # Verify the resolved path is a regular file, not a symlink
    if os.path.islink(storage_path):
        return {"error": "Invalid file reference"}
    if not os.path.isfile(storage_path):
        return {"error": "File missing from storage"}

    with open(storage_path, 'rb') as f:
        content = f.read()

    return {"success": True, "filename": filename, "content": content}

def share_file(owner, file_id, target_user):
    """Share a file with another user by creating a copy."""
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.execute(
        "SELECT owner, filename, storage_key, content_hash FROM files WHERE id = ?",
        (file_id,)
    )
    row = cursor.fetchone()

    if not row:
        conn.close()
        return {"error": "File not found"}

    file_owner, filename, storage_key, content_hash = row

    if file_owner != owner:
        conn.close()
        return {"error": "Not your file"}

    validated_target = validate_owner(target_user)
    if not validated_target:
        conn.close()
        return {"error": "Invalid target user"}

    # Create a new storage key for the shared copy
    new_storage_key = generate_storage_key(validated_target, filename)
    new_storage_path = get_storage_path(new_storage_key)
    original_storage_path = get_storage_path(storage_key)

    # Verify original is not a symlink before copying
    if os.path.islink(original_storage_path):
        conn.close()
        return {"error": "Invalid source file"}

    os.makedirs(os.path.dirname(new_storage_path), exist_ok=True)
    # Use file copy for isolation between users
    import shutil
    shutil.copy2(original_storage_path, new_storage_path)

    conn.execute(
        "INSERT INTO files (owner, filename, storage_key, content_hash, created_at) VALUES (?, ?, ?, ?, ?)",
        (validated_target, filename, new_storage_key, content_hash, time.time())
    )
    conn.commit()
    conn.close()

    return {"success": True}

def delete_file(owner, file_id):
    """Delete a file."""
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.execute(
        "SELECT owner, storage_key FROM files WHERE id = ?",
        (file_id,)
    )
    row = cursor.fetchone()

    if not row:
        conn.close()
        return {"error": "File not found"}

    file_owner, storage_key = row
    if file_owner != owner:
        conn.close()
        return {"error": "Not your file"}

    storage_path = get_storage_path(storage_key)
    if os.path.isfile(storage_path) and not os.path.islink(storage_path):
        os.unlink(storage_path)

    conn.execute("DELETE FROM files WHERE id = ?", (file_id,))
    conn.commit()
    conn.close()

    return {"success": True}

def search_files(requesting_user, query):
    """Search files by filename pattern."""
    validated_user = validate_owner(requesting_user)
    if not validated_user:
        return {"error": "Invalid user"}

    # Sanitize the query to prevent LIKE injection
    safe_query = query.replace('%', '').replace('_', '').replace('[', '')
    if not safe_query or len(safe_query) > 100:
        return {"error": "Invalid query"}

    conn = sqlite3.connect(DB_PATH)
    # Only search user's own files and public files
    cursor = conn.execute(
        "SELECT id, owner, filename, created_at FROM files WHERE (owner = ? OR is_public = 1) AND filename LIKE ?",
        (validated_user, f"%{safe_query}%")
    )
    results = [{"id": r[0], "owner": r[1], "filename": r[2], "created_at": r[3]} for r in cursor.fetchall()]
    conn.close()

    return {"results": results}

def create_session(username):
    """Create an authenticated session."""
    validated = validate_owner(username)
    if not validated:
        return None
    token = secrets.token_urlsafe(32)
    expires = time.time() + 3600
    conn = sqlite3.connect(DB_PATH)
    conn.execute(
        "INSERT INTO sessions (token, username, expires_at) VALUES (?, ?, ?)",
        (token, validated, expires)
    )
    conn.commit()
    conn.close()
    return token

def validate_session(token):
    """Validate a session token."""
    if not token or len(token) > 128:
        return None
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.execute(
        "SELECT username, expires_at FROM sessions WHERE token = ?",
        (token,)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    username, expires_at = row
    if time.time() > expires_at:
        return None
    return username

class FileHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > MAX_FILE_SIZE + 4096:
            self.send_error(413)
            return

        body = self.rfile.read(content_length)

        if self.path == '/upload':
            token = self.headers.get('Authorization', '').replace('Bearer ', '')
            user = validate_session(token)
            if not user:
                self.send_error(401)
                return

            try:
                meta_end = body.index(b'\n\n')
                meta = json.loads(body[:meta_end])
                file_content = body[meta_end+2:]
            except (ValueError, json.JSONDecodeError):
                self.send_error(400)
                return

            result = store_file(user, meta.get('filename', ''), file_content)
            self.send_response(200 if 'success' in result else 400)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(result).encode())

        elif self.path == '/share':
            token = self.headers.get('Authorization', '').replace('Bearer ', '')
            user = validate_session(token)
            if not user:
                self.send_error(401)
                return

            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self.send_error(400)
                return

            result = share_file(user, data.get('file_id'), data.get('target_user', ''))
            self.send_response(200 if 'success' in result else 400)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(result).encode())

    def do_GET(self):
        token = self.headers.get('Authorization', '').replace('Bearer ', '')
        user = validate_session(token)
        if not user:
            self.send_error(401)
            return

        if self.path.startswith('/file/'):
            try:
                file_id = int(self.path[6:])
            except ValueError:
                self.send_error(400)
                return

            result = retrieve_file(user, file_id)
            if 'error' in result:
                self.send_error(404 if result['error'] == 'File not found' else 403)
                return

            self.send_response(200)
            self.send_header('Content-Type', 'application/octet-stream')
            self.send_header('Content-Disposition', f'attachment; filename="{result["filename"]}"')
            self.end_headers()
            self.wfile.write(result['content'])

        elif self.path.startswith('/search'):
            query = unquote(self.path.split('q=', 1)[-1]) if 'q=' in self.path else ''
            result = search_files(user, query)
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(result).encode())

if __name__ == '__main__':
    init_db()
    server = HTTPServer(('127.0.0.1', 8080), FileHandler)
    server.serve_forever()
